// Mobile family-care prototype. All people, medications and events are fictional.
const ICONS={cross:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 5 2 2 5-5"/>',clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 11h6m-6 4h6m-6 4h3"/>',box:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M7 7V4h10v3M3 12h18m-11 4h4"/>',bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 5"/>',leaf:'<path d="M20 3c-9-1-17 4-15 12 7 5 16-2 15-12Z"/><path d="m3 21 12-13"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m8 10 4 4 4-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pill:'<path d="m10 4-6 6a6 6 0 0 0 8 8l6-6a6 6 0 0 0-8-8Z"/><path d="m7 7 10 10"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4 8 8 0 1 0 20 14Z"/>',cloud:'<path d="M6 18a4 4 0 0 1-1-8 6 6 0 0 1 11-3 5 5 0 0 1 2 11H6Z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',shield:'<path d="m12 2 8 3v6c0 5-8 11-8 11S4 16 4 11V5l8-3Z"/><path d="m8 11 3 3 5-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',edit:'<path d="m15 3 6 6M3 21l5-1L21 7l-5-5L3 15v6Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',heart:'<path d="M20 5c-3-3-6 0-8 2-2-2-5-5-8-2-4 4 3 10 8 15 5-5 12-11 8-15Z"/>',undo:'<path d="M3 10h11a7 7 0 0 1 0 14M3 10l5-5m-5 5 5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',stop:'<circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>'};
Object.assign(ICONS,{home:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3V10Z"/>',alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v.2"/>',phone:'<path d="m5 3 4 5-3 3c2 4 3 5 7 7l3-3 5 4c-1 4-4 4-7 3C6 18 2 12 2 6c0-2 1-3 3-3Z"/>',watch:'<rect x="5" y="6" width="14" height="12" rx="4"/><path d="m8 6 1-5h6l1 5M8 18l1 5h6l1-5m-5-9v3l2 1"/>',speaker:'<rect x="5" y="3" width="14" height="18" rx="6"/><ellipse cx="12" cy="7" rx="4" ry="2"/><path d="M9 15h6m-6 3h6"/>',camera:'<rect x="3" y="6" width="18" height="14" rx="3"/><path d="m8 6 2-3h4l2 3"/><circle cx="12" cy="13" r="4"/>',back:'<path d="m15 5-7 7 7 7"/>',send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'});
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.pill}</svg>`;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?.()||'id'+Date.now()+Math.random().toString(36).slice(2);
function iso(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateObj(s){return new Date(s+'T12:00:00')}
function addDays(s,n){let d=dateObj(s);d.setDate(d.getDate()+n);return iso(d)}
const diffDays=(a,b)=>Math.round((dateObj(b)-dateObj(a))/86400000);
const fmt=(s,opts={day:'numeric',month:'long'})=>dateObj(s).toLocaleDateString('ru-RU',opts);
const hm=n=>String(Math.floor(n/60)%24).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
const mins=s=>Number(s.slice(0,2))*60+Number(s.slice(3,5));
const plural=(n,forms)=>forms[n%100>=11&&n%100<=14?2:n%10===1?0:n%10>=2&&n%10<=4?1:2];
const DAY=iso(),KEY='aptechka_family_mobile_v1';
const seed=()=>({version:1,day:DAY,clock:825,role:'anna',patient:{name:'Нина Петровна',short:'Мама',age:74,city:'Тверь'},members:[{id:'anna',name:'Анна',relation:'Дочь',role:'owner',view:true,mark:true,stock:true,alerts:true},{id:'elena',name:'Елена',relation:'Сиделка',role:'caregiver',view:true,mark:true,stock:false,alerts:true},{id:'max',name:'Максим',relation:'Внук',role:'family',view:true,mark:false,stock:false,alerts:true}],courses:[{id:'course1',title:'После выписки',start:addDays(DAY,-3),days:14,active:true,demo:true,source:'Учебная выписка',meds:[{id:'a',name:'Препарат А',strength:'10 мг',form:'Таблетки',unit:'табл.',dose:1,times:['08:00','20:00'],note:'После еды',pack:20,color:''},{id:'b',name:'Препарат Б',strength:'5 мг',form:'Таблетки',unit:'табл.',dose:1,times:['13:00'],note:'Во время еды',pack:14,color:'sand'},{id:'c',name:'Препарат В',strength:'20 мг',form:'Капсулы',unit:'капс.',dose:1,times:['08:30'],note:'По учебному назначению',pack:30,color:'lilac'}]}],stock:[{id:'sa',name:'Препарат А',strength:'10 мг',form:'Таблетки',unit:'табл.',qty:8,pack:20},{id:'sb',name:'Препарат Б',strength:'5 мг',form:'Таблетки',unit:'табл.',qty:5,pack:14},{id:'sc',name:'Препарат В',strength:'20 мг',form:'Капсулы',unit:'капс.',qty:16,pack:30}],logs:{[`course1|a|${DAY}|08:00`]:{status:'taken',actor:'elena',actorName:'Елена',source:'observed',time:'08:03',consumed:1,stockId:'sa',note:'Помогла с утренним приёмом.'},[`course1|c|${DAY}|08:30`]:{status:'taken',actor:'elena',actorName:'Елена',source:'reported',time:'08:35',consumed:1,stockId:'sc',note:'Нина Петровна сообщила о приёме.'}},signalState:{},settings:{grace:30,backup:'anna',notifications:true},audit:[{id:'seed2',type:'taken',dose:`course1|c|${DAY}|08:30`,title:'Елена отметила приём',detail:'Препарат В · со слов близкого',date:DAY,time:'08:35'},{id:'seed1',type:'taken',dose:`course1|a|${DAY}|08:00`,title:'Елена отметила приём',detail:'Препарат А · наблюдала лично',date:DAY,time:'08:03'}]});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=seed()}catch{state=seed()}
let view=(location.hash||'#home').slice(1),selectedDate=state.day,planFilter='all',stockTab='stock',draft=null,files=[],fileURL=null,toastTimer,lastFocus;
const views=['home','plan','stock','signals','family','courses','devices','history'];if(!views.includes(view))view='home';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Не удалось сохранить данные в браузере. Скачайте журнал.') }}
const actor=()=>state.role==='senior'?{id:'senior',name:state.patient.name,role:'senior',view:true,mark:true,stock:false,alerts:false}:state.members.find(m=>m.id===state.role)||state.members[0];
const owner=()=>actor().role==='owner';
const canViewCourse=c=>owner()||actor().id==='senior'||!c.importMethod||c.helper===actor().id;
const visibleAudit=()=>state.audit.filter(a=>{const id=a.courseId||a.dose?.split('|')[0];const c=state.courses.find(c=>c.id===id);return !c||canViewCourse(c)});
const canMark=()=>!!actor().mark;const canStock=()=>!!actor().stock;
const sourceText={observed:'наблюдала лично',reported:'со слов близкого',self:'отметка родственника'};
function audit(type,title,detail='',dose=null){state.audit.unshift({id:uid(),type,title,detail,dose,date:state.day,time:hm(state.clock)});state.audit=state.audit.slice(0,250)}
const norm=s=>String(s).trim().toLowerCase().replace(/\s+/g,' ');
const medKey=m=>[m.name,m.strength,m.form,m.unit].map(norm).join('|');
const stockFor=m=>state.stock.find(s=>medKey(s)===medKey(m));
function events(date){return state.courses.flatMap(c=>canViewCourse(c)&&c.active&&diffDays(c.start,date)>=0&&diffDays(c.start,date)<c.days?c.meds.filter(m=>diffDays(c.start,date)<(m.days||c.days)).flatMap(m=>m.times.map(t=>{const id=[c.id,m.id,date,t].join('|');return{id,course:c,med:m,date,time:t,log:state.logs[id]}})):[]).sort((a,b)=>a.time.localeCompare(b.time))}
function eventById(id){const [cid,mid,date,time]=(id||'').split('|');const c=state.courses.find(c=>c.id===cid),m=c?.meds.find(m=>m.id===mid);return c&&canViewCourse(c)&&m&&date&&time?{id,course:c,med:m,date,time,log:state.logs[id]}:null}
const isPast=e=>e.date<state.day||(e.date===state.day&&mins(e.time)<=state.clock);
const delayed=e=>!['taken','skipped'].includes(e.log?.status)&&e.date===state.day&&state.clock-mins(e.time)>=state.settings.grace;
function signals(){return events(state.day).filter(e=>((delayed(e)||e.log?.status==='skipped')&&!state.signalState[e.id]?.resolved)).map(e=>({...e,signal:state.signalState[e.id]||{}}))}
function shopping(){const needs=new Map();for(const c of state.courses.filter(c=>c.active)){for(let d=0;d<c.days;d++){const date=addDays(c.start,d);if(date<state.day)continue;for(const m of c.meds){if(d>=(m.days||c.days))continue;for(const t of m.times){const id=[c.id,m.id,date,t].join('|');if(['taken','skipped'].includes(state.logs[id]?.status))continue;const key=medKey(m);if(!needs.has(key))needs.set(key,{med:m,needed:0,stock:stockFor(m),end:addDays(c.start,(m.days||c.days)-1)});needs.get(key).end=[needs.get(key).end,addDays(c.start,(m.days||c.days)-1)].sort().at(-1);needs.get(key).needed+=m.dose}}}}return [...needs.values()].map(n=>{let qty=n.stock?.expiry&&n.stock.expiry<n.end?0:n.stock?.qty||0,missing=Math.max(0,Math.round((n.needed-qty)*100)/100),pack=n.stock?.pack||n.med.pack;return{...n,qty,missing,pack,packs:pack?Math.ceil(missing/pack):null}}).filter(n=>n.missing>0)}
function toast(msg,undo){clearTimeout(toastTimer);$('#toastRoot').innerHTML=`<div class="toast">${esc(msg)}${undo?'<button id="toastUndo">Отменить</button>':''}</div>`;if(undo)$('#toastUndo').onclick=()=>{undo();$('#toastRoot').innerHTML=''};toastTimer=setTimeout(()=>$('#toastRoot').innerHTML='',4500)}
function head(title,subtitle='',back=false,action=''){return `<div class="page-head"><div class="between"><div class="${back?'back-title':''}">${back?`<button class="icon-btn" data-nav="home" aria-label="Назад">${icon('back')}</button>`:''}<h1>${title}</h1></div>${action}</div>${subtitle?`<p>${subtitle}</p>`:''}</div>`}
function footer(){return `<div class="footnote">Учебное демо · данные остаются в этом браузере<br><button class="text-link" data-action="about">О прототипе и его возможностях</button></div>`}
function portrait(){return '<div class="portrait" aria-hidden="true"><svg viewBox="0 0 68 74"><path d="M11 75c1-18 10-27 23-27s22 9 24 27" fill="#668ca5"/><path d="M28 43h12v12c-4 6-8 6-12 0" fill="#dfba98"/><ellipse cx="34" cy="30" rx="18" ry="22" fill="#e8c7a7"/><path d="M15 29C10 2 47-1 53 18l-1 13-5-13c-7 6-15 6-23 3l-7 12" fill="#dde5eb"/><path d="M17 22c-2-15 8-22 18-20 14-2 21 11 18 24-3-12-5-12-10-15-6 8-13 10-26 11" fill="#f7f9fb"/><g stroke="#7c806d" fill="none" stroke-width="1.1"><rect x="21" y="28" width="11" height="8" rx="3"/><rect x="37" y="28" width="11" height="8" rx="3"/><path d="M32 30h5m-7 12q5 4 10 0"/></g><circle cx="27" cy="32" r="1" fill="#777466"/><circle cx="42" cy="32" r="1" fill="#777466"/><path d="m24 53 10 10 10-10" fill="#e9f0f5"/></svg></div>'}
function render(){if(state.role!=='senior'&&!state.members.some(m=>m.id===state.role&&m.view))state.role='anna';const a=actor();$('#app').classList.toggle('senior',state.role==='senior');$('#header').innerHTML=`<div class="between"><a class="brand" href="#home"><span class="brand-mark">${icon('cross')}</span>аптечка</a><button class="profile-btn" data-action="roles" aria-label="Переключить демо-роль"><span class="avatar ${a.role==='caregiver'?'sand':''}">${esc(a.name.slice(0,1))}</span>${esc(a.name.split(' ')[0])}${icon('chevron')}</button></div><div class="header-note"><span><i class="dot"></i>Рядом, даже на расстоянии</span><button class="text-link demo-clock" data-action="demoClock">Демо · ${hm(state.clock)}</button></div>`;$('#nav').innerHTML=[['home','home','Обзор'],['plan','calendar','План'],['stock','box','Аптечка'],['signals','bell','Сигналы'],['family','users','Семья']].map(([v,i,l])=>`<button data-nav="${v}" aria-label="${l}" class="${view===v?'active':''}" aria-current="${view===v?'page':'false'}">${icon(i)}<span>${l}</span>${v==='signals'&&signals().length?'<i class="nav-dot"></i>':''}</button>`).join('');$('#main').innerHTML=state.role==='senior'?seniorView():`${!owner()?`<div class="mode-banner">Демо-роль: ${esc(a.relation)} · ${esc(a.name)}</div>`:''}${({home:homeView,plan:planView,stock:stockView,signals:signalsView,family:familyView,courses:coursesView,devices:devicesView,history:historyView}[view])()}`;document.title='Аптечка — '+({home:'Забота о маме',plan:'План лечения',stock:'Аптечка',signals:'Сигналы',family:'Круг заботы',courses:'Назначения',devices:'Устройства',history:'Журнал заботы'}[view]);}
function navigate(v){if(!views.includes(v))return;view=v;location.hash=v;render();window.scrollTo({top:0,behavior:'instant'})}
function homeView(){const ev=events(state.day),done=ev.filter(e=>e.log?.status==='taken').length,sg=signals(),need=shopping();return `${head('Как дела у мамы?','Самое важное о близком — с первого взгляда.')}<section class="patient-card"><div class="patient-person">${portrait()}<div><h2>${esc(state.patient.name)}</h2><p>${esc(state.patient.age)} года · ${esc(state.patient.city)}</p><span class="label patient-relation">${esc(state.patient.short)}</span></div><button class="chevron" data-action="patient" aria-label="Профиль родственника">${icon('chevron')}</button></div><div class="status-line"><span>Приёмы за сегодня</span><strong>${done} из ${ev.length} отмечены</strong></div><div class="mini-progress"><span style="width:${ev.length?done/ev.length*100:0}%"></span></div></section>${sg.length?alertCard(sg[0],true):`<div class="quiet-card row">${icon('check')}<div><h3>Сейчас нет открытых сигналов</h3><p>Это статус отметок, а не оценка самочувствия.</p></div></div>`}${owner()?`<button class="import-entry" data-action="import"><span class="scan-symbol">${icon('file')}</span><span><strong>Распознать назначение</strong><small>Фото или PDF → готовый план</small></span><span class="import-entry-arrow">${icon('arrow')}</span></button>`:''}<div class="quick-grid"><button class="quick-card" data-nav="courses"><span class="quick-icon">${icon('file')}<span class="arrow">${icon('arrow')}</span></span><strong>Назначения врача</strong><small>${state.courses.filter(c=>c.active&&canViewCourse(c)).length} ${plural(state.courses.filter(c=>c.active&&canViewCourse(c)).length,['активный курс','активных курса','активных курсов'])}</small></button><button class="quick-card" data-action="shopping"><span class="quick-icon">${icon('bag')}<span class="arrow">${icon('arrow')}</span></span><strong>Нужно докупить</strong><small>${need.length?`${need.length} ${plural(need.length,['препарат','препарата','препаратов'])} на курс`:'Запасов хватает'}</small></button></div><div class="section-top between"><h2>Сегодня по плану</h2><button class="text-link" data-nav="plan">Весь день ${icon('arrow')}</button></div><div class="card">${ev.slice(0,3).map(doseRow).join('')||empty('Пока нет плана','Добавьте назначение, чтобы создать расписание.')}</div><div class="section-top between"><h2>Вы заботитесь вместе</h2><button class="text-link" data-nav="family">Круг заботы ${icon('arrow')}</button></div><div class="card">${visibleAudit().slice(0,2).map(activityRow).join('')}</div><div class="future-card"><span class="orb">${icon('watch')}</span><div><h3>Больше уверенности в будущем</h3><p>Датчики, голосовые напоминания и события с камер — следующий этап.</p><button class="text-link" data-nav="devices">Посмотреть возможности ${icon('arrow')}</button></div></div>${footer()}`}
function empty(title,desc){return `<div class="empty"><div class="empty-illustration">${icon('leaf')}</div><h3>${title}</h3><p>${desc}</p></div>`}
function signalLabel(e){return e.log?.status==='skipped'?'Приём отмечен пропущенным':'Нет подтверждения приёма'}
function alertCard(e,compact=false){const s=state.signalState[e.id]||{},elapsed=Math.max(0,state.clock-mins(e.time));return `<section class="alert"><div class="row"><span class="alert-icon">${icon('alert')}</span><div class="grow"><h3>${signalLabel(e)}</h3><p>${esc(e.med.name)} · ${e.time}</p></div><span class="alert-time">${e.log?.status==='skipped'?'пропуск':elapsed+' мин'}</span></div><p style="margin-top:12px">${s.owner?`${esc(s.owner)} проверяет ситуацию.`:'Отметки пока нет. Это не значит, что лекарство точно пропущено.'}${s.snoozedUntil>state.clock?` Повторный сигнал в ${hm(s.snoozedUntil)}.`:''}</p><div class="alert-actions"><button class="btn btn-primary btn-small" data-action="event" data-id="${esc(e.id)}">Проверить приём ${icon('arrow')}</button>${!compact?`<button class="btn btn-white btn-small" data-action="claim" data-id="${esc(e.id)}" ${s.owner?'disabled':''}>Я проверю</button>`:''}</div>${compact&&signals().length>1?`<button class="text-link" style="margin-top:13px" data-nav="signals">Ещё сигналов: ${signals().length-1}</button>`:''}</section>`}
function doseRow(e){const l=e.log,taken=l?.status==='taken',skip=l?.status==='skipped',unknown=delayed(e),status=taken?'Отмечено':skip?'Пропуск':unknown?'Нет отметки':'По плану',cls=skip||unknown?'red':taken?'':'gray';return `<div class="dose-row ${unknown||skip?'uncertain':''}"><span class="time">${e.time}</span><div class="grow"><div class="med-name"><h3>${esc(e.med.name)}</h3><span class="label ${cls}">${status}</span></div><p>${esc(e.med.strength)} · ${e.med.dose} ${esc(e.med.unit)} · ${esc(e.med.note)}</p><div class="dose-source ${unknown||skip?'warn':''}">${icon(taken?'users':unknown?'alert':'clock')}${taken?`${esc(l.actorName)} · ${esc(sourceText[l.source]||'отметка')} · ${l.time}`:skip?`${esc(l.actorName)} · ${esc(l.note||'причина не указана')}`:unknown?'Семье нужен ответ':e.log?.snoozedUntil?`Напомнить в ${hm(e.log.snoozedUntil)}`:'Ожидается отметка о приёме'}</div></div><button class="detail-link" data-action="event" data-id="${esc(e.id)}" aria-label="Открыть приём ${esc(e.med.name)} в ${e.time}"></button></div>`}
function activityRow(a){const who=a.title.startsWith('Елена')?'Е':'А';return `<div class="care-activity"><span class="avatar ${who==='Е'?'sand':''}">${who}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.detail)}<br>${a.date===state.day?'Сегодня':fmt(a.date)} в ${a.time}</p></div></div>`}
function planView(){const start=addDays(selectedDate,-((dateObj(selectedDate).getDay()+6)%7)),ev=events(selectedDate),visible=planFilter==='all'?ev:ev.filter(e=>!['taken','skipped'].includes(e.log?.status));return `${head('План лечения',`${esc(state.patient.name)} · ${fmt(selectedDate)}`,false,owner()?`<button class="icon-btn" data-action="import" aria-label="Добавить назначение">${icon('plus')}</button>`:'')}<div class="day-wrap"><button class="day-nav" data-action="prevWeek" aria-label="Предыдущая неделя">${icon('back')}</button><div class="week">${Array.from({length:7},(_,i)=>{const d=addDays(start,i);return `<button class="day ${d===selectedDate?'active':''}" data-date="${d}" aria-label="${fmt(d)}"><span>${fmt(d,{weekday:'short'})}</span><b>${dateObj(d).getDate()}</b></button>`}).join('')}</div><button class="day-nav" data-action="nextWeek" aria-label="Следующая неделя">${icon('arrow')}</button></div><div class="segmented"><button data-filter="all" class="${planFilter==='all'?'active':''}">Все приёмы</button><button data-filter="pending" class="${planFilter==='pending'?'active':''}">Без отметки</button></div><div class="card">${visible.map(doseRow).join('')||empty('На этот день всё','Нет приёмов, которые соответствуют выбранному фильтру.')}</div><p class="caption">У каждой отметки есть автор и способ подтверждения. Отметка человека не является независимой проверкой приёма.</p><button class="btn btn-white btn-full space" data-nav="courses">${icon('file')} Назначения и курсы</button>${footer()}`}
function signalsView(){const sg=signals();return `${head('Сигналы семье',`${sg.length?`${sg.length} ${plural(sg.length,['ситуация требует','ситуации требуют','ситуаций требуют'])} внимания`:'Все ситуации проверены'}.`,false,owner()?`<button class="icon-btn" data-action="signalSettings" aria-label="Настроить сигналы">${icon('bell')}</button>`:'')}<div class="hint orange">${icon('info')}<span>Если отметки нет спустя ${state.settings.grace} минут, появляется сигнал. Свяжитесь с близким или тем, кто рядом.</span></div>${sg.map(e=>alertCard(e)).join('')||`<div class="card space">${empty('Сейчас спокойно','Открытых сигналов нет. История действий семьи сохранена в журнале.')}</div>`}<div class="section-top between"><h2>Кто подстрахует</h2><button class="text-link" data-action="signalSettings">Настроить</button></div><div class="card padded"><div class="row"><span class="avatar">${esc((state.members.find(m=>m.id===state.settings.backup)?.name||'Анна').slice(0,1))}</span><div><h3>${esc(state.members.find(m=>m.id===state.settings.backup)?.name||'Анна')}</h3><p class="small muted" style="margin-top:4px">Резервный ответственный</p></div></div><p class="caption">При отсутствии реакции в течение ещё 30 минут сигнал помечается для резервного ответственного. В демо внешняя отправка отключена.</p></div><button class="btn btn-white btn-full space" data-nav="history">${icon('clock')} Журнал заботы</button>${footer()}`}
function stockView(){return `${head('Аптечка мамы','Остатки дома и покупки на текущий курс.',false,canStock()?`<button class="icon-btn" data-action="addStock" aria-label="Добавить препарат">${icon('plus')}</button>`:'')}<div class="segmented"><button data-stock-tab="stock" class="${stockTab==='stock'?'active':''}">Дома · ${state.stock.length}</button><button data-stock-tab="buy" class="${stockTab==='buy'?'active':''}">Докупить · ${shopping().length}</button></div>${stockTab==='stock'?`<label class="search">${icon('search')}<input id="stockSearch" aria-label="Найти препарат" placeholder="Название препарата"></label><div class="card" id="stockList">${stockRows('')}</div><p class="caption">При подтверждении приёма остаток уменьшается один раз. Отмена отметки возвращает списанное количество.</p>`:shoppingView()}${footer()}`}
function stockRows(q){return state.stock.filter(s=>norm(s.name+s.strength).includes(norm(q))).map(s=>{const need=shopping().find(n=>n.stock?.id===s.id);return `<div class="list-item"><span class="med-icon">${icon('pill')}</span><div class="grow"><h3>${esc(s.name)}</h3><p>${esc(s.strength)} · ${esc(s.form)}</p><p class="caption">${s.expiry?'Годен до '+fmt(s.expiry):'Срок годности не проверен'}</p>${need?'<span class="label orange" style="margin-top:7px">На курс не хватит</span>':''}</div><div class="qty">${s.qty}<small>${esc(s.unit)}</small></div>${canStock()?`<button class="ghost" data-action="editStock" data-id="${esc(s.id)}" aria-label="Изменить ${esc(s.name)}">${icon('edit')}</button>`:''}</div>`}).join('')||empty('Ничего не найдено','Добавьте препарат или измените поиск.')}
function shoppingView(){const list=shopping();return `<div class="hint">${icon('bag')}<span>Учитываем оставшиеся приёмы, точное название, форму и дозировку. Если размер упаковки известен, округляем до целых упаковок. Запас с истекающим до конца курса сроком не учитываем.</span></div><div class="card space">${list.map((n,i)=>`<div class="buy-card"><div class="row"><span class="med-icon ${n.med.color||''}">${icon('pill')}</span><div class="grow"><h3>${esc(n.med.name)}</h3><p>${esc(n.med.strength)} · ${esc(n.med.form)}</p></div><span class="label orange">${n.packs?n.packs+' уп.':n.missing+' '+esc(n.med.unit)}</span></div><div class="formula">Нужно ${n.needed} − дома ${n.qty} = <strong>${n.missing} ${esc(n.med.unit)}</strong></div><div class="between"><span class="small muted">${n.pack?'По '+n.pack+' '+esc(n.med.unit)+' в упаковке':'Размер упаковки не указан'}</span>${canStock()?`<button class="btn btn-soft btn-small" data-action="buy" data-index="${i}">${icon('check')} Куплено</button>`:''}</div></div>`).join('')||empty('Запасов хватает','По текущим данным покупать больше не нужно.')}</div><button class="btn btn-white btn-full space" data-action="exportShopping">${icon('download')} Скачать список покупок</button>`}
function familyView(){return `${head('Круг заботы','У каждого своя роль. У семьи — общая картина.',false,owner()?`<button class="icon-btn" data-action="invite" aria-label="Добавить помощника">${icon('plus')}</button>`:'')}<div class="hint">${icon('shield')}<span>Доступ предоставляется с согласия близкого или на основании полномочий законного представителя.</span></div><div class="card space">${state.members.map(m=>`<section class="person-card"><div class="row"><span class="avatar ${m.role==='caregiver'?'sand':''}">${esc(m.name.slice(0,1))}</span><div class="grow"><h3>${esc(m.name)} ${m.id===state.role?'<span class="label gray">Вы</span>':''}</h3><p>${esc(m.relation)} · ${m.role==='owner'?'организатор ухода':m.view?'доступ разрешён':'доступ отозван'}</p></div>${owner()&&m.role!=='owner'?`<button class="text-link" data-action="permissions" data-id="${esc(m.id)}">Права</button>`:''}</div>${m.role==='caregiver'?'<p class="caption">Отмечает помощь и способ подтверждения. Все действия сохраняются в журнале.</p>':''}</section>`).join('')}</div><button class="btn btn-white btn-full space" data-action="roles">${icon('eye')} Посмотреть глазами близкого или сиделки</button><div class="section-top between"><h2>Последние действия</h2><button class="text-link" data-nav="history">Все ${icon('arrow')}</button></div><div class="card">${visibleAudit().slice(0,3).map(activityRow).join('')}</div><p class="caption">Роли переключаются в этом браузере для демонстрации. Реальные приглашения и синхронизация между людьми не подключены.</p>${footer()}`}
function historyView(){return `${head('Журнал заботы','Кто, когда и на каком основании сделал отметку.',true,`<button class="icon-btn" data-action="exportHistory" aria-label="Скачать журнал">${icon('download')}</button>`)}<div class="hint gray">${icon('users')}<span>«Наблюдала лично» — заявление автора отметки. Данных с устройств или видео в этом MVP нет.</span></div><div class="history">${visibleAudit().map(a=>`<div class="history-item"><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><p>${fmt(a.date)} · ${a.time}</p></div>`).join('')}</div>${footer()}`}
function coursesView(){return `${head('Назначения врача','Из выписки — в понятный план для всей семьи.',true)}${owner()?`<button class="btn btn-primary btn-full" data-action="import">${icon('upload')} Распознать назначение</button>`:''}<div class="card space">${state.courses.filter(canViewCourse).map(c=>`<section class="course-card"><div class="between"><span class="label ${c.active?'':'gray'}">${c.active?'Активный курс':'Завершён'}</span>${c.demo?'<span class="label gray">Учебный пример</span>':''}</div><h3>${esc(c.title)}</h3><p>${fmt(c.start)} — ${fmt(addDays(c.start,c.days-1))} · ${c.days} дней</p><div class="course-meds">${c.meds.map(m=>`<div class="course-med"><strong>${esc(m.name)} · ${esc(m.strength)}</strong><br><span>${m.dose} ${esc(m.unit)} · ${m.times.join(', ')} · ${m.days||c.days} дней · ${esc(m.note)}</span></div>`).join('')}</div><div class="between"><button class="text-link" data-nav="plan">К расписанию ${icon('arrow')}</button>${owner()&&c.active?`<button class="ghost" data-action="endCourse" data-id="${esc(c.id)}">Завершить курс</button>`:''}</div><p class="caption">Источник: ${esc(c.source)}. ${c.demo?'Схема вымышлена.':'Оригинал доступен только во время импорта.'}</p></section>`).join('')||empty('Пока нет назначений','Добавьте выписку или назначение врача.')}</div><p class="caption">Новая схема требует проверки каждого препарата. Приложение не выбирает лечение и не возобновляет старые назначения.</p>${footer()}`}
function devicesView(){return `${head('Устройства и наблюдение','Следующий этап продукта — отдельный пилот.',true)}<div class="hint orange">${icon('info')}<span>Интеграции ещё не подключены. Здесь нет реальных измерений, видео или объективно подтверждённых приёмов.</span></div><div class="card space">${[['watch','Устройства здоровья','Показатели и события от совместимых устройств, в том числе ночью. Сигналы настраиваются вместе с медицинскими специалистами.'],['speaker','Голосовой помощник','Простое напоминание близкому и передача его ответа семье. Голосовой ответ сам по себе не доказывает приём.'],['camera','Хронология событий по видео','Просмотр разрешённых записей по времени: визит сиделки, помощь, предполагаемый приём. Автоматическое распознавание требует проверки качества.']].map(([i,t,p])=>`<div class="device-card"><div class="between"><span class="med-icon">${icon(i)}</span><span class="label gray">Следующий этап</span></div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="mini-article"><h3>Контроль с понятными границами</h3><p>Подключение наблюдения — с согласия близкого либо на законном основании, с определёнными зонами, сроками хранения и доступами. В журнале должны отдельно отображаться слова человека, события устройства и результат ручной проверки.</p></div>${footer()}`}
function seniorView(){const pending=events(state.day).filter(e=>!['taken','skipped'].includes(e.log?.status)),e=pending[0];return `<h1 class="senior-title">Здравствуйте,<br>${esc(state.patient.name)}!</h1><p class="senior-sub">Ваш план на сегодня</p>${e?`<section class="senior-card"><div class="time-big">${e.time}</div><div class="med-icon ${e.med.color||''}">${icon('pill')}</div><h2>${esc(e.med.name)}</h2><p>${esc(e.med.strength)}<br>${e.med.dose} ${esc(e.med.unit)} · ${esc(e.med.note)}</p>${isPast(e)?`<button class="btn btn-primary btn-full" data-action="seniorTake" data-id="${esc(e.id)}">${icon('check')} Я приняла</button>`:'<p>Время приёма ещё не наступило.</p>'}<p class="caption">Отмечайте только после приёма.</p></section>`:`<section class="senior-card"><div class="empty-illustration">${icon('check')}</div><h2>Всё отмечено</h2><p>На сегодня больше нет ожидающих приёмов.</p></section>`}<button class="btn btn-white senior-call" data-action="contact">${icon('phone')} Связаться с семьёй</button><p class="caption">Семья увидит вашу отметку.<br>Демо: данные обновляются в этом браузере.</p><button class="btn btn-soft btn-full space" data-action="ownerRole">Вернуться к экрану семьи</button>`}
function sheet(title,subtitle,body,foot=''){lastFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="sheets"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheetTitle"><div class="sheet-handle"></div><div class="sheet-head"><div><h2 id="sheetTitle">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="close-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="sheet-body">${body}</div>${foot?`<div class="sheet-foot">${foot}</div>`:''}</section></div>`;document.body.style.overflow='hidden';$('#app').inert=true;setTimeout(()=>$('.close-btn')?.focus(),10)}
function closeSheet(){if(typeof stopImport==='function')stopImport();if(fileURL){URL.revokeObjectURL(fileURL);fileURL=null}$('#modalRoot').innerHTML='';$('#app').inert=false;document.body.style.overflow='';lastFocus?.focus?.();draft=null;files=[]}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function eventSheet(id){const e=eventById(id);if(!e)return;const l=e.log,s=state.signalState[id]||{},past=isPast(e),resolved=['taken','skipped'].includes(l?.status);sheet(`${e.time} · ${esc(e.med.name)}`,`${fmt(e.date)} · ${esc(state.patient.name)}`,`<div class="event-hero"><div class="med-icon ${e.med.color||''}">${icon('pill')}</div><h2>${esc(e.med.name)} · ${esc(e.med.strength)}</h2><p>${e.med.dose} ${esc(e.med.unit)} · ${esc(e.med.note)}</p></div>${l?.status==='taken'?`<div class="source-box"><p><strong>Отметка о приёме</strong><br>${esc(l.actorName)} · ${l.time}<br>Способ: ${esc(sourceText[l.source])}<br>${esc(l.note||'Без комментария')}</p></div><div class="hint gray">${icon('eye')}<span>Это запись человека. Независимого подтверждения устройством или видео нет.</span></div>`:l?.status==='skipped'?`<div class="hint orange">${icon('alert')}<span>Приём отмечен пропущенным.<br>${esc(l.actorName)} · ${esc(l.note||'Причина не указана')}</span></div>`:delayed(e)?`<div class="hint orange">${icon('alert')}<span>Нет отметки уже ${state.clock-mins(e.time)} минут. Сначала уточните у близкого или сиделки, состоялся ли приём.</span></div>`:'<div class="hint gray">По подтверждённому назначению. Действия при пропуске уточняйте у врача; приложение не меняет дозу.</div>'}<div class="responsible"><span class="avatar sand">Е</span><div class="grow"><strong>${s.owner?esc(s.owner)+' проверяет':'Елена · сиделка'}</strong><p>${s.owner?'Ответственный за этот сигнал':'Помогает с приёмом сегодня'}</p></div><button class="text-link" data-action="contact">Связаться ${icon('arrow')}</button></div>${!resolved&&past?`<div class="row wrap" style="margin-bottom:16px"><button class="btn btn-soft btn-small" data-action="claim" data-id="${esc(id)}" ${s.owner?'disabled':''}>${icon('users')} ${s.owner?'В работе':'Я проверю'}</button><button class="btn btn-white btn-small" data-action="request" data-id="${esc(id)}">${icon('send')} Демо-запрос отметки</button></div>`:''}${s.requested?`<p class="caption">Демо-запрос создан в ${s.requested}. Реальное сообщение не отправлено.</p>`:''}${delayed(e)&&state.clock-mins(e.time)>=state.settings.grace+30?`<div class="hint orange space">${icon('bell')}<span>Нужна реакция резервного ответственного: ${esc(state.members.find(m=>m.id===state.settings.backup)?.name||'Анна')}.</span></div>`:''}${canMark()&&resolved&&(owner()||l.actor===actor().id)?`<button class="btn btn-white btn-full space" data-action="undo" data-id="${esc(id)}">${icon('undo')} Исправить отметку</button>`:''}${!resolved&&canMark()&&past?`<button class="ghost space" style="width:100%" data-action="skipForm" data-id="${esc(id)}">Отметить пропуск</button>`:''}${l?.status==='skipped'&&!s.resolved&&actor().role!=='senior'?`<button class="btn btn-soft btn-full space" data-action="resolve" data-id="${esc(id)}">Ситуация проверена семьёй</button>`:''}<p class="caption">Источник схемы: ${esc(e.course.source)}.</p>`,!resolved&&canMark()&&past?`<button class="btn btn-white" data-action="snooze" data-id="${esc(id)}">${icon('clock')} Напомнить</button><button class="btn btn-primary" data-action="confirmForm" data-id="${esc(id)}">Отметить приём</button>`:`<button class="btn btn-white" data-action="close">Закрыть</button>`)}
function confirmForm(id){const e=eventById(id);if(!e||!canMark()||!isPast(e))return;sheet('Подтвердить приём',`${esc(e.med.name)} · ${e.time}`,`<form id="confirmForm" data-id="${esc(id)}"><p class="small muted">Как вы узнали, что близкий принял препарат?</p><div class="source-select"><label class="radio-card"><input type="radio" name="source" value="observed" required>Наблюдала лично</label><label class="radio-card"><input type="radio" name="source" value="reported" required>Со слов близкого или сиделки</label></div><label class="field"><span>Комментарий для семьи</span><textarea name="note" maxlength="250" placeholder="Что важно знать близким"></textarea></label><div class="hint gray">${icon('users')}<span>Автор отметки: ${esc(actor().name)}. Семья увидит способ подтверждения и время.</span></div><label class="check-row"><input type="checkbox" name="confirmed" required>Отмечаю состоявшийся приём, а не намерение принять.</label></form>`,`<button class="btn btn-white" data-action="event" data-id="${esc(id)}">Назад</button><button class="btn btn-primary" form="confirmForm" type="submit">${icon('check')} Подтвердить</button>`)}
function take(id,source,note=''){const e=eventById(id);if(!e||!canMark()||!isPast(e)||['taken','skipped'].includes(state.logs[id]?.status))return;const st=stockFor(e.med),consumed=st&&(!st.expiry||st.expiry>=state.day)?Math.min(st.qty,e.med.dose):0;if(st)st.qty=Math.round((st.qty-consumed)*100)/100;const a=actor();state.logs[id]={status:'taken',actor:a.id,actorName:a.name,source,note,time:hm(state.clock),consumed,stockId:st?.id||null};state.signalState[id]={...(state.signalState[id]||{}),resolved:true};audit('taken',a.name+' отметила приём',e.med.name+' · '+sourceText[source]+(note?' · '+note:''),id);save();closeSheet();render();toast(consumed<e.med.dose?'Приём отмечен. В аптечке недостаточно учтённых остатков.':'Отметка сохранена. Семья видит автора и подтверждение.');}
function undo(id){const l=state.logs[id];if(!l||!canMark()||(!owner()&&l.actor!==actor().id))return;const s=state.stock.find(s=>s.id===l.stockId);if(s&&l.status==='taken')s.qty=Math.round((s.qty+(l.consumed||0))*100)/100;delete state.logs[id];state.signalState[id]={};audit('undo',actor().name+' исправила отметку',eventById(id)?.med.name+' · предыдущая отметка отменена',id);save();closeSheet();render();toast('Отметка отменена. Списанный остаток восстановлен.')}
function skipForm(id){const e=eventById(id);if(!e||!canMark()||!isPast(e))return;sheet('Отметить пропуск',`${esc(e.med.name)} · ${e.time}`,`<form id="skipForm" data-id="${esc(id)}"><label class="field"><span>Причина или комментарий</span><select name="reason" required><option value="">Выберите причину</option><option>Близкий отказался</option><option>Забыли о приёме</option><option>Препарата нет дома</option><option>Уточняем схему у врача</option><option>Другое</option></select></label><label class="field"><span>Дополнение</span><textarea name="note" maxlength="200"></textarea></label><div class="hint orange">${icon('info')}<span>Пропуск появится в журнале и сигналах семье. Приложение не рекомендует переносить или удваивать дозу.</span></div></form>`,`<button class="btn btn-white" data-action="event" data-id="${esc(id)}">Назад</button><button class="btn btn-primary" type="submit" form="skipForm">Сохранить пропуск</button>`)}
function skip(id,reason,note){const e=eventById(id);if(!e||!canMark()||!isPast(e)||['taken','skipped'].includes(e.log?.status))return;const a=actor();state.logs[id]={status:'skipped',actor:a.id,actorName:a.name,time:hm(state.clock),note:reason+(note?' · '+note:''),consumed:0};state.signalState[id]={};audit('skipped',a.name+' отметила пропуск',e.med.name+' · '+reason,id);save();closeSheet();render();toast('Пропуск сохранён. В сигналах семье появилась запись.')}
function claim(id){if(actor().role==='senior')return;const e=eventById(id);if(!e)return;state.signalState[id]={...(state.signalState[id]||{}),owner:actor().name};audit('claim',actor().name+' проверяет приём',e.med.name+' · '+e.time,id);save();render();eventSheet(id)}
function request(id){const e=eventById(id);if(!e)return;state.signalState[id]={...(state.signalState[id]||{}),requested:hm(state.clock)};audit('request','Создан демо-запрос для сиделки',e.med.name+' · запросить уточнение приёма',id);save();render();eventSheet(id);toast('Демо-запрос сохранён. Реальное сообщение не отправлялось.')}
function snooze(id){const e=eventById(id);if(!e||!canMark())return;sheet('Повторить напоминание','Переносится только напоминание, схема лечения остаётся прежней.',`<div class="stack"><button class="btn btn-soft btn-full" data-action="setSnooze" data-id="${esc(id)}" data-minutes="15">Через 15 минут · ${hm(state.clock+15)}</button><button class="btn btn-white btn-full" data-action="setSnooze" data-id="${esc(id)}" data-minutes="30">Через 30 минут · ${hm(state.clock+30)}</button><p class="caption">В демо время можно изменить нажатием на часы в шапке. Фоновая доставка уведомлений не подключена.</p></div>`)}
function roles(){sheet('Посмотреть с другой стороны','Демонстрация ролей в одном браузере.',`${state.members.filter(m=>m.view).map(m=>`<button class="role-choice ${state.role===m.id?'selected':''}" data-action="setRole" data-id="${esc(m.id)}"><span class="avatar ${m.role==='caregiver'?'sand':''}">${esc(m.name.slice(0,1))}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.relation)} · ${m.role==='owner'?'организует уход':m.mark?'может отмечать приёмы':'смотрит план и журнал'}</p></div></button>`).join('')}<button class="role-choice" data-action="setRole" data-id="senior"><span class="avatar rose">Н</span><div><h3>${esc(state.patient.name)}</h3><p>Крупный интерфейс для самого близкого</p></div></button><p class="caption">Это не авторизация. В реальном сервисе роли доступны только после входа и проверки доступа.</p>`)}
function contact(){sheet('Связаться с тем, кто рядом','В демо используются вымышленные люди.',`${state.members.filter(m=>m.view&&m.id!==actor().id).map(m=>`<div class="responsible"><span class="avatar ${m.role==='caregiver'?'sand':''}">${esc(m.name.slice(0,1))}</span><div class="grow"><strong>${esc(m.name)}</strong><p>${esc(m.relation)}</p></div><button class="btn btn-soft btn-small" data-action="demoCall" data-name="${esc(m.name)}">${icon('phone')} Позвонить</button></div>`).join('')}<p class="caption">Демо-звонки показывают сценарий связи. Телефонные номера и отправка сообщений не подключены.</p>`)}
function permissions(id){if(!owner())return;const m=state.members.find(m=>m.id===id);if(!m||m.role==='owner')return;sheet('Доступ: '+esc(m.name),esc(m.relation),`<div class="permissions">${[['view','Смотреть план и журнал'],['mark','Отмечать приёмы'],['stock','Менять остатки и покупки'],['alerts','Получать сигналы']].map(([key,label])=>`<label class="permission">${label}<input type="checkbox" class="switch" data-member="${esc(id)}" data-permission="${key}" ${m[key]?'checked':''} ${key!=='view'&&!m.view?'disabled':''}></label>`).join('')}</div><p class="caption">Изменения применяются сразу к демонстрационной роли. Отзыв просмотра отключает остальные права.</p>`,`<button class="btn btn-primary" data-action="close">Готово</button>`)}
function invite(){if(!owner())return;sheet('Добавить в круг заботы','Выберите роль и основание доступа.',`<form id="inviteForm">${field('Имя','name','','text','required maxlength="40"')}<label class="field"><span>Роль</span><select name="role"><option value="family">Родственник</option><option value="caregiver">Сиделка</option></select></label><label class="field"><span>Основание доступа</span><select name="basis" required><option value="">Выберите</option><option>Есть согласие близкого</option><option>Есть полномочия законного представителя</option></select></label><label class="check-row"><input type="checkbox" name="consent" required>Подтверждаю основание. Разрешаю просмотр плана и журнала; дополнительные права настрою отдельно.</label><p class="caption">Будет добавлен локальный демо-участник. Приглашение не отправляется.</p></form>`,`<button class="btn btn-white" data-action="close">Отмена</button><button class="btn btn-primary" form="inviteForm" type="submit">Добавить</button>`)}
function signalSettings(){sheet('Настройки сигналов','Кому сообщить, если приём не отмечен.',`<form id="signalSettings"><label class="field"><span>Сигнал через</span><select name="grace" ${!owner()?'disabled':''}>${[15,30,60].map(n=>`<option value="${n}" ${n===state.settings.grace?'selected':''}>${n} минут без отметки</option>`).join('')}</select></label><label class="field"><span>Резервный ответственный</span><select name="backup" ${!owner()?'disabled':''}>${state.members.filter(m=>m.view&&m.role!=='caregiver').map(m=>`<option value="${esc(m.id)}" ${m.id===state.settings.backup?'selected':''}>${esc(m.name)} · ${esc(m.relation)}</option>`).join('')}</select></label><div class="hint gray">${icon('bell')}<span>Сигнал виден в приложении. Если ещё 30 минут нет отметки и никто не взял ситуацию в работу — добавляется резервный ответственный.</span></div><p class="caption">В демо нет отправки push, SMS и звонков. Реальная доставка — часть серверного MVP.</p></form>`,owner()?`<button class="btn btn-primary" type="submit" form="signalSettings">Сохранить</button>`:`<button class="btn btn-white" data-action="close">Закрыть</button>`)}
function patient(){sheet('Профиль близкого','Один родственник в этом прототипе.',`<form id="patientForm">${field('Имя','name',state.patient.name,'text',`required maxlength="60" ${!owner()?'disabled':''}`)}<div class="field-grid">${field('Возраст','age',state.patient.age,'number',`required min="18" max="120" ${!owner()?'disabled':''}`)}${field('Город','city',state.patient.city,'text',`required maxlength="50" ${!owner()?'disabled':''}`)}</div>${field('Как вы называете близкого','short',state.patient.short,'text',`required maxlength="25" ${!owner()?'disabled':''}`)}<div class="hint gray">${icon('heart')}<span>План доступен участникам круга заботы с разрешённым доступом.</span></div></form>`,owner()?`<button class="btn btn-primary" type="submit" form="patientForm">Сохранить</button>`:`<button class="btn btn-white" data-action="close">Закрыть</button>`)}
function editStock(id){if(!canStock())return;const s=state.stock.find(s=>s.id===id)||{name:'',strength:'',form:'Таблетки',qty:0,pack:20};sheet(id?'Изменить остаток':'Добавить препарат','Точное название, форма и дозировка нужны для сверки.',`<form id="stockForm" data-id="${esc(id||'')}">${field('Название','name',s.name,'text',`required maxlength="100" ${id?'readonly':''}`)}<div class="field-grid">${field('Дозировка','strength',s.strength,'text',`required maxlength="50" ${id?'readonly':''}`)}<label class="field"><span>Форма</span><select name="form" ${id?'disabled':''}><option ${s.form==='Таблетки'?'selected':''}>Таблетки</option><option ${s.form==='Капсулы'?'selected':''}>Капсулы</option></select></label>${field('Остаток, штук','qty',s.qty,'number','required min="0" max="100000" step="0.25"')}${field('Штук в упаковке','pack',s.pack,'number','required min="1" max="1000" step="1"')}</div>${field('Годен до','expiry',s.expiry||'','date','')}<div id="stockError" class="error" role="alert"></div><p class="caption">Для другого препарата добавьте отдельную позицию. Это сохраняет правильную связь с журналом.</p></form>`,`<button class="btn btn-white" data-action="close">Отмена</button><button class="btn btn-primary" form="stockForm" type="submit">Сохранить</button>`)}
function submitStock(form){if(!canStock())return;const d=new FormData(form),old=state.stock.find(s=>s.id===form.dataset.id);const s={id:old?.id||uid(),name:old?.name||String(d.get('name')||'').trim(),strength:old?.strength||String(d.get('strength')||'').trim(),form:old?.form||String(d.get('form')),qty:Number(d.get('qty')),pack:Number(d.get('pack')),expiry:String(d.get('expiry')||'')};s.unit=s.form==='Капсулы'?'капс.':'табл.';if(!s.name||!s.strength||!Number.isFinite(s.qty)||s.qty<0||s.qty>100000||s.qty*4%1||!Number.isInteger(s.pack)||s.pack<1||s.pack>1000){$('#stockError').textContent='Проверьте остаток и упаковку.';return}if(s.qty>0&&!/^\d{4}-\d{2}-\d{2}$/.test(s.expiry)){$('#stockError').textContent='Укажите срок годности запаса.';return}if(state.stock.some(x=>x.id!==s.id&&medKey(s)===medKey(x))){$('#stockError').textContent='Этот препарат уже есть в аптечке. Измените его остаток.';return}if(old)Object.assign(old,s);else state.stock.push(s);audit('stock',actor().name+' обновила аптечку',s.name+' · остаток '+s.qty+' '+s.unit);save();closeSheet();render();toast('Остаток сохранён, список покупок пересчитан.')}
function buy(index){if(!canStock())return;const n=shopping()[index];if(!n)return;sheet('Пополнить аптечку',`${esc(n.med.name)} · ${esc(n.med.strength)}`,`<form id="buyForm" data-key="${esc(medKey(n.med))}"><div class="hint">${icon('box')}<span>На остаток курса не хватает ${n.missing} ${esc(n.med.unit)}.</span></div><div class="space">${field('Сколько упаковок куплено','packs',n.packs||1,'number','required min="1" max="1000" step="1"')}${field('Штук в купленной упаковке','pack',n.pack||'','number','required min="1" max="1000" step="1"')}${field('Минимальный срок годности всего учитываемого запаса','expiry',n.stock?.expiry||'','date','required')}</div><p class="caption">Покупка не оформляется. Укажите минимальный срок старых и новых упаковок; просроченный запас сначала исключите в аптечке.</p><div id="buyError" class="error" role="alert"></div></form>`,`<button class="btn btn-white" data-action="close">Отмена</button><button class="btn btn-primary" form="buyForm" type="submit">Добавить в запас</button>`)}
function submitBuy(form){if(!canStock())return;const n=shopping().find(n=>medKey(n.med)===form.dataset.key),data=new FormData(form),packs=Number(data.get('packs')),pack=Number(data.get('pack')),expiry=String(data.get('expiry')||'');if(!n||!Number.isInteger(packs)||packs<1||packs>1000||!Number.isInteger(pack)||pack<1||pack>1000||!/^\d{4}-\d{2}-\d{2}$/.test(expiry)||expiry<state.day){$('#buyError').textContent='Проверьте количество, упаковку и срок годности.';return}if(n.stock?.qty>0&&n.stock.expiry&&expiry>n.stock.expiry){$('#buyError').textContent='У остатка дома более ранний срок. Укажите минимальный срок либо сначала скорректируйте остаток в аптечке.';return}let s=n.stock;if(!s){s={id:uid(),name:n.med.name,strength:n.med.strength,form:n.med.form,unit:n.med.unit,qty:0};state.stock.push(s)}s.qty+=packs*pack;s.pack=pack;s.expiry=expiry;audit('stock',actor().name+' пополнила запас',s.name+' · '+packs+' уп.');save();closeSheet();render();toast('Запас пополнен. Семья видит обновление.')}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportShopping(){download('aptechka-shopping.txt','АПТЕЧКА — СПИСОК ПОКУПОК\n'+state.patient.name+' · '+fmt(state.day)+'\n\n'+(shopping().map(n=>`${n.med.name} ${n.med.strength}, ${n.med.form}\nНужно ${n.needed} ${n.med.unit}, дома ${n.qty}, не хватает ${n.missing}.\n${n.packs?'Докупить '+n.packs+' уп. по '+n.pack+' '+n.med.unit:'Докупить '+n.missing+' '+n.med.unit+'. Размер упаковки уточните.'}`).join('\n\n')||'Запасов хватает.')+'\n\nУчебные препараты вымышлены. Не является медицинским назначением.')}
function exportHistory(){download('aptechka-care-journal.json',JSON.stringify({demo:true,patient:state.patient,note:'Записи людей, без независимого подтверждения приема',logs:state.logs,audit:state.audit},null,2),'application/json;charset=utf-8')}
function clockSheet(){sheet('Демонстрационное время',`${fmt(state.day)} · ${hm(state.clock)}`,`<p class="small muted">Время фиксировано для понятного показа сценария. Можно продвинуть его и увидеть новые сигналы и напоминания.</p><div class="stack space"><button class="btn btn-soft" data-action="advanceClock" data-minutes="30">Продвинуть на 30 минут</button><button class="btn btn-white" data-action="advanceClock" data-minutes="60">Продвинуть на час</button></div><p class="caption">Демонстрация не отправляет уведомления за пределы приложения.</p>`)}
function about(){sheet('Аптечка для семьи','Рядом с близким, даже если вы в другом городе.',`<div class="mini-article"><p><strong>Что работает:</strong> мобильный план родственника, распознавание печатных фото и PDF на устройстве, извлечение полей, проверка каждого препарата, отметки с автором и источником, сигналы, ответственный за проверку, журнал, остатки, докупка и права ролей.</p><p><strong>Что демонстрируется:</strong> роли в одном браузере, запросы сиделке и звонки, время для сигналов. Реальные аккаунты, push и семейная синхронизация не подключены.</p><p><strong>Что дальше:</strong> интеграции устройств, голосовых колонок и работа с видео. Отметка человека сейчас не представляется объективным подтверждением приёма.</p><p><strong>Хранение:</strong> локально в браузере. Исходные файлы и текст обрабатываются в этой вкладке и не отправляются на сервер. После импорта сохраняется только проверенный план. OCR может ошибаться; сложные схемы требуют уточнения. Поддерживается ежедневная схема постоянной дозы таблеток/капсул до 90 дней.</p><a class="text-link" href="analysis.html" target="_blank">Сводка материалов и состав MVP ${icon('arrow')}</a></div>`,`<button class="btn btn-white" data-action="reset">Сбросить демо</button><button class="btn btn-primary" data-action="close">Понятно</button>`)}
function handleAction(a,b){const id=b.dataset.id;const actions={close:closeSheet,about,roles,patient,contact,import:openImport,demoImport,exportShopping,exportHistory,demoClock:clockSheet,signalSettings,invite,shopping:()=>{stockTab='buy';navigate('stock')},gotoShopping:()=>{closeSheet();stockTab='buy';navigate('stock')},prevWeek:()=>{selectedDate=addDays(selectedDate,-7);render()},nextWeek:()=>{selectedDate=addDays(selectedDate,7);render()},event:()=>eventSheet(id),confirmForm:()=>confirmForm(id),skipForm:()=>skipForm(id),undo:()=>undo(id),claim:()=>claim(id),request:()=>request(id),snooze:()=>snooze(id),setSnooze:()=>{const e=eventById(id);if(!e||!canMark()||['taken','skipped'].includes(e.log?.status))return;const n=Number(b.dataset.minutes);if(![15,30].includes(n))return;const until=Math.min(1439,state.clock+n);state.logs[id]={status:'snoozed',snoozedUntil:until};state.signalState[id]={...(state.signalState[id]||{}),snoozedUntil:until};audit('snooze',actor().name+' отложила напоминание',e.med.name+' · до '+hm(until),id);save();closeSheet();render();toast('Повторное напоминание в '+hm(until)+'. Дозировка не менялась.')},resolve:()=>{if(actor().role==='senior'||state.logs[id]?.status!=='skipped')return;state.signalState[id]={...(state.signalState[id]||{}),resolved:true,owner:actor().name};audit('resolve',actor().name+' проверила пропуск',eventById(id)?.med.name+' · ситуация обработана, пропуск остаётся в журнале',id);save();closeSheet();render();toast('Сигнал обработан. Пропуск сохранён в журнале.')},seniorTake:()=>{if(state.role!=='senior')return;const e=eventById(id);if(!e||!isPast(e))return;sheet('Вы уже приняли лекарство?',`${esc(e.med.name)} · ${e.med.dose} ${esc(e.med.unit)}`,`<p style="font-size:17px;line-height:1.8">Подтвердите только состоявшийся приём. Семья увидит вашу отметку.</p>`,`<button class="btn btn-white" data-action="close">Ещё нет</button><button class="btn btn-primary" data-action="seniorConfirm" data-id="${esc(id)}">Да, приняла</button>`)},seniorConfirm:()=>{if(state.role==='senior')take(id,'self','Отмечено самим родственником')},setRole:()=>{if(id!=='senior'&&!state.members.some(m=>m.id===id&&m.view))return;state.role=id;save();closeSheet();view='home';location.hash='home';render();window.scrollTo(0,0)},ownerRole:()=>{state.role='anna';save();closeSheet();navigate('home')},permissions:()=>permissions(id),demoCall:()=>{sheet('Демо-звонок',esc(b.dataset.name),`<div class="empty"><div class="empty-illustration">${icon('phone')}</div><h3>Связаться с близким</h3><p>Здесь семья переходит к звонку ответственному. В прототипе звонок не совершается.</p></div>`,`<button class="btn btn-primary" data-action="close">Понятно</button>`)},addStock:()=>editStock(),editStock:()=>editStock(id),buy:()=>buy(Number(b.dataset.index)),addDraftMed:()=>{collectDraft();if(draft.meds.length>=8){toast('В одном курсе до 8 препаратов.');return}draft.meds.push(blankMed());draft.complete=false;draft.stockReview=null;reviewImport()},removeDraftMed:()=>{collectDraft();const removed=draft.meds.splice(Number(b.dataset.index),1)[0];if(removed?.name)draft.excluded.push(removed.name);draft.complete=false;draft.stockReview=null;reviewImport()},endCourse:()=>{if(!owner())return;const c=state.courses.find(c=>c.id===id);if(!c)return;sheet('Завершить курс?',esc(c.title),'<p class="small muted">Приёмы исчезнут из расписания. История семьи сохранится. Завершайте курс в соответствии с назначением врача.</p>',`<button class="btn btn-white" data-action="close">Отмена</button><button class="btn btn-primary" data-action="confirmEnd" data-id="${esc(id)}">Завершить</button>`)},confirmEnd:()=>{if(!owner())return;const c=state.courses.find(c=>c.id===id);if(!c)return;c.active=false;audit('course',actor().name+' завершила курс',c.title);save();closeSheet();render();toast('Курс завершён, журнал сохранён.')},advanceClock:()=>{const n=Number(b.dataset.minutes);if(![30,60].includes(n))return;state.clock=Math.min(1439,state.clock+n);save();closeSheet();render();toast('Демо-время: '+hm(state.clock)+'. Сигналы пересчитаны.')},reset:()=>{sheet('Начать демо заново?','Все изменения этого прототипа в браузере будут сброшены.',`<p class="small muted">Перед сбросом можно скачать журнал заботы.</p><button class="text-link space" data-action="exportHistory">${icon('download')} Скачать журнал</button>`,`<button class="btn btn-white" data-action="close">Отмена</button><button class="btn btn-danger" data-action="confirmReset">Сбросить</button>`)},confirmReset:()=>{state=seed();save();closeSheet();selectedDate=state.day;stockTab='stock';planFilter='all';navigate('home');toast('Демо восстановлено.')}};actions[a]?.()}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){closeSheet();navigate(nav.dataset.nav);return}const day=e.target.closest('[data-date]');if(day){selectedDate=day.dataset.date;render();return}const filt=e.target.closest('[data-filter]');if(filt){planFilter=filt.dataset.filter;render();return}const st=e.target.closest('[data-stock-tab]');if(st){stockTab=st.dataset.stockTab;render();return}const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b)});
document.addEventListener('input',e=>{if(e.target.id==='stockSearch')$('#stockList').innerHTML=stockRows(e.target.value);if(e.target.closest('#reviewForm')&&e.target.type!=='checkbox'){const med=e.target.closest('.review-med');if(med){const ch=$('input[type=checkbox]',med);if(ch)ch.checked=false}const final=$('#finalConsent');if(final)final.checked=false}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='prescriptionFiles')fileImport([...el.files]);if(el.id==='previewSelect'){if(fileURL)URL.revokeObjectURL(fileURL);const f=files[Number(el.value)];fileURL=URL.createObjectURL(f);$('#filePreview').innerHTML=previewFile(f,fileURL);$('#openOriginal').href=fileURL}if(el.dataset.permission&&owner()){const m=state.members.find(m=>m.id===el.dataset.member);if(!m||m.role==='owner')return;m[el.dataset.permission]=el.checked;if(!m.view){m.mark=false;m.stock=false;m.alerts=false}audit('permission',actor().name+' изменила доступ',m.name+' · '+(m.view?'права обновлены':'доступ отозван'));save();render();permissions(m.id)}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f),id=f.dataset.id;if(f.id==='confirmForm'){if(!d.has('confirmed')||!['observed','reported'].includes(d.get('source')))return;take(id,d.get('source'),String(d.get('note')||'').trim())}if(f.id==='skipForm'&&d.get('reason'))skip(id,String(d.get('reason')),String(d.get('note')||'').trim());if(f.id==='stockForm')submitStock(f);if(f.id==='buyForm')submitBuy(f);if(f.id==='reviewForm')submitCourse();if(f.id==='inviteForm'&&owner()){const name=String(d.get('name')||'').trim(),role=String(d.get('role'));if(!name||!d.has('consent')||!d.get('basis')||!['family','caregiver'].includes(role))return;state.members.push({id:uid(),name,relation:role==='caregiver'?'Сиделка':'Родственник',role,view:true,mark:false,stock:false,alerts:true,basis:String(d.get('basis'))});audit('invite',actor().name+' добавила участника',name+' · демо-доступ только для просмотра');save();closeSheet();render();toast('Участник добавлен локально. Приглашение не отправлялось.')}if(f.id==='signalSettings'&&owner()){const grace=Number(d.get('grace')),backup=String(d.get('backup'));if(![15,30,60].includes(grace)||!state.members.some(m=>m.id===backup&&m.view))return;state.settings.grace=grace;state.settings.backup=backup;save();closeSheet();render();toast('Настройки сигналов сохранены.')}if(f.id==='patientForm'&&owner()){const name=String(d.get('name')||'').trim(),city=String(d.get('city')||'').trim(),short=String(d.get('short')||'').trim(),age=Number(d.get('age'));if(!name||!city||!short||!Number.isInteger(age)||age<18||age>120)return;state.patient={name,city,short,age};save();closeSheet();render();toast('Профиль близкого обновлён.')}});
document.addEventListener('keydown',e=>{if(!$('#modalRoot').children.length)return;if(e.key==='Escape'){closeSheet();return}if(e.key==='Tab'){const els=$$('button,a[href],input:not([type=hidden]),select,textarea,summary',$('#modalRoot')).filter(x=>!x.disabled&&x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(views.includes(v)){view=v;render()}});
save();render();
